begin;
create extension if not exists pgtap with schema extensions;
set search_path to public, extensions;
select plan(19);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values
('18310000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','mcp183-confirm@example.invalid','x',now(),now());
insert into public.organizations(id,name) values ('18310000-0000-0000-0000-000000000002','Synthetic');
insert into public.organization_members(organization_id,user_id,role) values ('18310000-0000-0000-0000-000000000002','18310000-0000-0000-0000-000000000001','owner');
insert into auth.oauth_clients(id,registration_type,redirect_uris,grant_types,client_type,token_endpoint_auth_method) values ('18310000-0000-0000-0000-000000000003','dynamic','http://localhost/callback','authorization_code','public','none');
insert into auth.oauth_consents(id,user_id,client_id,scopes) values ('18310000-0000-0000-0000-000000000004','18310000-0000-0000-0000-000000000001','18310000-0000-0000-0000-000000000003','openid');
insert into private.mcp_reauth_proofs(user_id,client_id,consent_granted_at,verified_at) select user_id,client_id,granted_at,clock_timestamp() from auth.oauth_consents where id='18310000-0000-0000-0000-000000000004';
insert into auth.sessions(id,user_id,oauth_client_id,created_at) values ('18310000-0000-0000-0000-000000000005','18310000-0000-0000-0000-000000000001','18310000-0000-0000-0000-000000000003',now());
insert into public.user_session_activity(session_hash,auth_session_id,user_id,last_activity,absolute_expires_at) values ('mcp183-browser','mcp183-browser','18310000-0000-0000-0000-000000000001',now(),now()+interval '1 hour');
insert into public.clients(id,organization_id,name) values ('18310000-0000-0000-0000-000000000006','18310000-0000-0000-0000-000000000002','Synthetic client');
insert into public.form_templates(client_id,schema) values ('18310000-0000-0000-0000-000000000006','[{"id":"note","label":"Note","type":"text"}]');
insert into public.reports(id,client_id,helper_id,service_date,status,start_at,end_at) values ('18310000-0000-0000-0000-000000000007','18310000-0000-0000-0000-000000000006','18310000-0000-0000-0000-000000000001','2026-10-28','pending','2026-10-28 01:00+00','2026-10-28 02:00+00');
insert into public.report_values(report_id,data) values ('18310000-0000-0000-0000-000000000007','{"note":"before"}');
insert into private.mcp_record_read_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18310000-0000-0000-0000-000000000002',true,'{}','18310000-0000-0000-0000-000000000001',now());
insert into private.mcp_record_edit_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18310000-0000-0000-0000-000000000002',true,'{}','18310000-0000-0000-0000-000000000001',now());
select set_config('request.jwt.claims','{"sub":"18310000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18310000-0000-0000-0000-000000000003","session_id":"18310000-0000-0000-0000-000000000005"}',true);
insert into private.mcp_report_transition_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18310000-0000-0000-0000-000000000002',true,'{}','18310000-0000-0000-0000-000000000001',now());
insert into public.reports(id,client_id,helper_id,service_date,status,start_at,end_at) values ('18310000-0000-0000-0000-000000000008','18310000-0000-0000-0000-000000000006','18310000-0000-0000-0000-000000000001','2026-10-28','pending','2026-10-28 02:00+00','2026-10-28 03:00+00');
insert into public.report_values(report_id,data) values ('18310000-0000-0000-0000-000000000008','{"note":"second"}');
select throws_ok($$select public.prepare_mcp_report_transition_batch('18310000-0000-0000-0000-000000000002','[]','approve',null)$$,'22023','invalid_report_transition','empty batch is rejected');
select throws_ok($$select public.prepare_mcp_report_transition_batch('18310000-0000-0000-0000-000000000002','[{"record_id":"18310000-0000-0000-0000-000000000007","expected_version":0},{"record_id":"18310000-0000-0000-0000-000000000007","expected_version":0}]','approve',null)$$,'22023','invalid_report_transition','duplicate records are rejected');
select is((select count(*)::int from private.mcp_report_transition_proposals),0,'a failed preparation leaves no partial proposals');
create temp table batch_id as select (public.prepare_mcp_report_transition_batch('18310000-0000-0000-0000-000000000002',jsonb_build_array(jsonb_build_object('record_id','18310000-0000-0000-0000-000000000007','expected_version',0),jsonb_build_object('record_id','18310000-0000-0000-0000-000000000008','expected_version',0)),'approve',null)->>'batch_id')::uuid as id;
select is((select count(*)::int from public.reports where id in ('18310000-0000-0000-0000-000000000007','18310000-0000-0000-0000-000000000008') and status='pending'),2,'preparing batch changes no report');
select throws_ok($$select private.review_mcp_report_transition_batch((select id from batch_id),true)$$,'42501','proposal_unavailable','MCP cannot confirm batch');
select set_config('request.jwt.claims','{"sub":"18310000-0000-0000-0000-000000000001","role":"authenticated","session_id":"mcp183-browser"}',true);
select is((private.review_mcp_report_transition_batch((select id from batch_id),false)->>'count')::int,2,'review includes both targets');
savepoint changed;
update public.report_values set data='{"note":"changed"}' where report_id='18310000-0000-0000-0000-000000000008';
select throws_ok($$select private.review_mcp_report_transition_batch((select id from batch_id),true)$$,'22023','proposal_changed','changed second record rejects entire batch');
select is((select count(*)::int from public.reports where id in ('18310000-0000-0000-0000-000000000007','18310000-0000-0000-0000-000000000008') and status='pending'),2,'conflict leaves both records unchanged');
rollback to savepoint changed;
savepoint audit_failure;
create function public.mcp183_batch_fail_audit() returns trigger language plpgsql set search_path='' as $$ begin if new.action_type='report.mcp_transition.confirm' and new.resource_id='18310000-0000-0000-0000-000000000008' then raise exception 'fixture_audit_failed'; end if; return new; end $$;
create trigger mcp183_batch_fail_audit before insert on public.audit_events for each row execute function public.mcp183_batch_fail_audit();
select throws_ok($$select private.review_mcp_report_transition_batch((select id from batch_id),true)$$,'P0001','fixture_audit_failed','second audit failure rejects batch');
select is((select count(*)::int from public.reports where id in ('18310000-0000-0000-0000-000000000007','18310000-0000-0000-0000-000000000008') and status='pending'),2,'audit failure rolls back first update');
rollback to savepoint audit_failure;
select is(private.review_mcp_report_transition_batch((select id from batch_id),true)->>'status','completed','confirmed batch succeeds');
select is((select count(*)::int from public.reports where id in ('18310000-0000-0000-0000-000000000007','18310000-0000-0000-0000-000000000008') and status='approved'),2,'both reports approved');
select is((private.review_mcp_report_transition_batch((select id from batch_id),true)->>'replayed')::boolean,true,'batch replay does not update again');
select is((select count(*)::int from public.audit_events where action_type='report.mcp_transition.confirm'),2,'replay does not duplicate audit');
select ok(not has_function_privilege('mcp_import','public.confirm_mcp_report_transition_batch(uuid)','execute'),'MCP cannot invoke browser confirmation');
select set_config('request.jwt.claims','{"sub":"18310000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18310000-0000-0000-0000-000000000003","session_id":"18310000-0000-0000-0000-000000000005"}',true);
create temp table remand_batch as select (public.prepare_mcp_report_transition_batch('18310000-0000-0000-0000-000000000002',jsonb_build_array(jsonb_build_object('record_id','18310000-0000-0000-0000-000000000007','expected_version',(select current_version from public.reports where id='18310000-0000-0000-0000-000000000007')),jsonb_build_object('record_id','18310000-0000-0000-0000-000000000008','expected_version',(select current_version from public.reports where id='18310000-0000-0000-0000-000000000008'))),'remand','Synthetic reason')->>'batch_id')::uuid as id;
select is(public.get_mcp_report_transition_batch_result('18310000-0000-0000-0000-000000000002',(select id from remand_batch))->>'status','confirmation_required','MCP can query pending batch');
select set_config('request.jwt.claims','{"sub":"18310000-0000-0000-0000-000000000001","role":"authenticated","session_id":"mcp183-browser"}',true);
select is(private.review_mcp_report_transition_batch((select id from remand_batch),true)->>'status','completed','batch remand succeeds');
select is((select count(*)::int from public.reports where id in ('18310000-0000-0000-0000-000000000007','18310000-0000-0000-0000-000000000008') and status='remanded'),2,'both reports are remanded');
select is(public.get_mcp_report_remand_reason('18310000-0000-0000-0000-000000000002','18310000-0000-0000-0000-000000000008'),'Synthetic reason','reason is available to the second record reader');
select * from finish();
rollback;
